callGraph.callee:
fused
    .map((f) => {
      const c = chunkMap.get(f.chunkId);
      if (!c) return null;
      return {
        chunkId: c.chunkId,
        docId: c.docId,
        relPath: c.relPath,
        title: c.title,
        headingPath: c.headingPath,
        text: c.text,
        source: c.source,
        scope: c.scope as Scope,
        score: f.score,
        vectorRank: vectorRank.get(f.chunkId) ?? null,
        bm25Rank: bm25Rank.get(f.chunkId) ?? null,
      } satisfies SearchHit;
    })
    .filter
